<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>DeployCloud Blog — Discover the latest in web development</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
:root {
  --bg: #FAFAFA;
  --surface: #FFFFFF;
  --text: #171717;
  --text-secondary: #555555;
  --text-tertiary: #888888;
  --accent: #0072F5;
  --accent-hover: #005FCC;
  --accent-light: #E8F1FD;
  --border: #E8E8E8;
  --border-light: #F0F0F0;
  --muted: #F5F5F5;
  --success: #22C55E;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.06);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.08);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --font-display: 'Space Grotesk', sans-serif;
  --font-body: 'DM Sans', sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
  --max-width: 1280px;
  --header-height: 60px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Subtle grain texture on body */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n' x='0' y='0'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.025'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
  pointer-events: none;
  z-index: 9999;
  opacity: 0.5;
}

/* ===== HEADER ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  transition: box-shadow 0.2s;
}
.header.scrolled { box-shadow: var(--shadow-md); }

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 32px;
  height: var(--header-height);
  display: flex;
  align-items: center;
  gap: 28px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--text);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: -0.3px;
  flex-shrink: 0;
}
.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--text);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 16px;
  font-weight: 700;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
  flex: 1;
}

.nav-item { position: relative; }

.nav-trigger {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 14px;
  border: none;
  background: none;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: all 0.15s;
  white-space: nowrap;
}
.nav-trigger:hover { color: var(--text); background: var(--muted); }
.nav-trigger.active { color: var(--text); background: var(--muted); }

.nav-trigger .chevron {
  width: 14px;
  height: 14px;
  transition: transform 0.2s;
}
.nav-trigger.active .chevron { transform: rotate(180deg); }

.nav-link {
  padding: 8px 14px;
  text-decoration: none;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: all 0.15s;
  white-space: nowrap;
}
.nav-link:hover { color: var(--text); background: var(--muted); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.btn-ghost {
  padding: 8px 16px;
  border: none;
  background: none;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: all 0.15s;
  white-space: nowrap;
}
.btn-ghost:hover { color: var(--text); background: var(--muted); }

.btn-primary {
  padding: 9px 20px;
  border: none;
  background: var(--text);
  color: #fff;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: all 0.15s;
  white-space: nowrap;
}
.btn-primary:hover { background: #333; }

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: 28px 32px;
  display: none;
  opacity: 0;
  transition: opacity 0.2s, transform 0.2s;
  width: max-content;
  max-width: calc(100vw - 64px);
}
.mega-menu.visible {
  display: flex;
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

.mega-col {
  min-width: 220px;
  padding: 0 24px;
}
.mega-col + .mega-col { border-left: 1px solid var(--border-light); }

.mega-col-title {
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--text-tertiary);
  margin-bottom: 14px;
}

.mega-item {
  display: block;
  padding: 8px 10px;
  margin: 0 -10px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  transition: background 0.15s;
  margin-bottom: 2px;
}
.mega-item:hover { background: var(--muted); }

.mega-item-name {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
}

.mega-item-desc {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--text-tertiary);
  margin-top: 1px;
}

/* Mobile menu toggle */
.mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  z-index: 101;
}
.mobile-toggle span {
  display: block;
  width: 20px;
  height: 2px;
  background: var(--text);
  border-radius: 1px;
  transition: transform 0.2s, opacity 0.2s;
}
.mobile-toggle.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.mobile-toggle.open span:nth-child(2) { opacity: 0; }
.mobile-toggle.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Mobile nav overlay */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--surface);
  z-index: 99;
  overflow-y: auto;
  padding: 20px 24px;
  border-top: 1px solid var(--border);
}
.mobile-nav.open { display: block; }

.mobile-nav-section {
  padding: 12px 0;
  border-bottom: 1px solid var(--border-light);
}
.mobile-nav-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 12px 0;
  border: none;
  background: none;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
}
.mobile-nav-trigger .chevron { transition: transform 0.2s; }
.mobile-nav-trigger.open .chevron { transform: rotate(180deg); }

.mobile-submenu {
  display: none;
  padding: 4px 0 12px 16px;
}
.mobile-submenu.open { display: block; }

.mobile-submenu a {
  display: block;
  padding: 8px 0;
  text-decoration: none;
  font-size: 14px;
  color: var(--text-secondary);
  transition: color 0.15s;
}
.mobile-submenu a:hover { color: var(--text); }

.mobile-submenu .sub-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--text-tertiary);
  padding: 10px 0 4px;
}

/* ===== MAIN CONTENT ===== */
.main { max-width: var(--max-width); margin: 0 auto; padding: 0 32px; }

/* ===== FEATURED SECTION ===== */
.featured-section {
  padding: 56px 0 40px;
  position: relative;
}

.featured-section::before {
  content: '';
  position: absolute;
  top: -80px;
  left: 50%;
  transform: translateX(-50%);
  width: 100vw;
  height: calc(100% + 80px);
  background: linear-gradient(180deg, #F0F4FA 0%, var(--bg) 100%);
  z-index: -1;
}

.featured-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: var(--accent);
  margin-bottom: 12px;
}
.featured-label::before {
  content: '';
  width: 6px;
  height: 6px;
  background: var(--accent);
  border-radius: 50%;
}

.featured-title {
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -1.2px;
  line-height: 1.1;
  margin-bottom: 10px;
  max-width: 700px;
}

.featured-subtitle {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 560px;
  line-height: 1.5;
}

/* Featured Cards Grid */
.featured-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 40px;
}

.featured-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  display: flex;
  flex-direction: column;
  transition: all 0.25s;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}
.featured-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
  border-color: #d0d0d0;
}

.featured-card:first-child {
  border-top: 3px solid var(--accent);
}

.featured-card-tag {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--accent);
  background: var(--accent-light);
  padding: 3px 10px;
  border-radius: 100px;
  margin-bottom: 14px;
  align-self: flex-start;
}

.featured-card-meta {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text-tertiary);
  margin-bottom: 10px;
}

.featured-card-title {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.4px;
  line-height: 1.3;
  margin-bottom: 10px;
  flex: 1;
}

.featured-card-excerpt {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.55;
  margin-bottom: 18px;
  flex: 1;
}

.featured-card-author {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
}

.author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--muted);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 700;
  color: var(--text-secondary);
  flex-shrink: 0;
}

/* Stats Ribbon */
.stats-ribbon {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-top: 28px;
  padding: 24px 28px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
}

.stat-item {
  text-align: center;
  padding: 0 8px;
}

.stat-value {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.6px;
  color: var(--accent);
  line-height: 1;
  margin-bottom: 6px;
}

.stat-label {
  font-size: 12px;
  color: var(--text-tertiary);
  line-height: 1.4;
}

/* ===== CATEGORY FILTERS ===== */
.filters-section {
  padding: 8px 0 28px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 40px;
}

.filters-inner {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.pills-row {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  flex: 1;
}

.pill {
  padding: 7px 16px;
  border: 1px solid var(--border);
  background: var(--surface);
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border-radius: 100px;
  transition: all 0.18s;
  white-space: nowrap;
  user-select: none;
}
.pill:hover { border-color: #c0c0c0; color: var(--text); }
.pill.active {
  background: var(--text);
  color: #fff;
  border-color: var(--text);
}

.search-wrap {
  position: relative;
  flex-shrink: 0;
  width: 240px;
}

.search-wrap svg {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  color: var(--text-tertiary);
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 9px 14px 9px 40px;
  border: 1px solid var(--border);
  background: var(--surface);
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--text);
  border-radius: 100px;
  outline: none;
  transition: all 0.18s;
}
.search-input::placeholder { color: var(--text-tertiary); }
.search-input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(0,114,245,0.1); }

/* ===== LATEST NEWS ===== */
.news-section { padding-bottom: 48px; }

.news-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 28px;
}
.news-title {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.6px;
}
.news-count {
  font-size: 13px;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
}

.posts-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.post-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 24px;
  display: flex;
  flex-direction: column;
  transition: all 0.2s;
  cursor: pointer;
}
.post-card:hover {
  box-shadow: var(--shadow-md);
  border-color: #d0d0d0;
  transform: translateY(-1px);
}

.post-card-tag {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  padding: 3px 10px;
  border-radius: 100px;
  margin-bottom: 12px;
  align-self: flex-start;
}
.tag-general { color: #666; background: #f0f0f0; }
.tag-engineering { color: #0072F5; background: #E8F1FD; }
.tag-community { color: #7C3AED; background: #EDE9FE; }
.tag-company { color: #059669; background: #D1FAE5; }
.tag-customers { color: #D97706; background: #FEF3C7; }
.tag-v0 { color: #DB2777; background: #FCE7F3; }
.tag-security { color: #DC2626; background: #FEE2E2; }
.tag-changelog { color: #0891B2; background: #CFFAFE; }
.tag-press { color: #4B5563; background: #F3F4F6; }

.post-card-date {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-tertiary);
  margin-bottom: 8px;
}

.post-card-title {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.3px;
  line-height: 1.35;
  margin-bottom: 8px;
  flex: 1;
}

.post-card-excerpt {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
  margin-bottom: 16px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-card-author {
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
}

/* Hidden posts for show more */
.hidden-posts { display: none; }
.hidden-posts.visible { display: grid; margin-top: 20px; }

.show-more-wrap {
  text-align: center;
  margin-top: 32px;
}

.btn-show-more {
  padding: 12px 36px;
  border: 1px solid var(--border);
  background: var(--surface);
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  border-radius: 100px;
  transition: all 0.18s;
}
.btn-show-more:hover { border-color: var(--text); box-shadow: var(--shadow-sm); }

.no-results {
  display: none;
  text-align: center;
  padding: 48px 20px;
}
.no-results.visible { display: block; }

.no-results-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 16px;
  background: var(--muted);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.no-results-icon svg { width: 22px; height: 22px; color: var(--text-tertiary); }

.no-results-title {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 6px;
}
.no-results-desc {
  font-size: 14px;
  color: var(--text-secondary);
}

/* ===== CTA SECTION ===== */
.cta-section {
  background: var(--text);
  border-radius: var(--radius-lg);
  padding: 56px 56px 48px;
  margin-bottom: 64px;
  color: #fff;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: '';
  position: absolute;
  top: -60px;
  right: -60px;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(0,114,245,0.3) 0%, transparent 70%);
  border-radius: 50%;
}

.cta-section::after {
  content: '';
  position: absolute;
  bottom: -40px;
  left: 30%;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, rgba(0,114,245,0.15) 0%, transparent 70%);
  border-radius: 50%;
}

.cta-content { position: relative; z-index: 1; }

.cta-title {
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -0.8px;
  line-height: 1.15;
  margin-bottom: 14px;
  max-width: 650px;
}

.cta-desc {
  font-size: 16px;
  color: rgba(255,255,255,0.65);
  max-width: 520px;
  line-height: 1.5;
  margin-bottom: 32px;
}

.cta-buttons {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

.btn-cta-primary {
  padding: 13px 28px;
  border: none;
  background: var(--accent);
  color: #fff;
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  border-radius: 100px;
  transition: all 0.18s;
}
.btn-cta-primary:hover { background: var(--accent-hover); }

.btn-cta-secondary {
  padding: 13px 28px;
  border: 1px solid rgba(255,255,255,0.25);
  background: transparent;
  color: #fff;
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  border-radius: 100px;
  transition: all 0.18s;
}
.btn-cta-secondary:hover { border-color: rgba(255,255,255,0.4); background: rgba(255,255,255,0.05); }

.cta-enterprise {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.cta-enterprise-text h4 {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 600;
  margin-bottom: 4px;
}
.cta-enterprise-text p {
  font-size: 14px;
