<script>
(function() {

// ===== HEADER SCROLL SHADOW =====
const header = document.getElementById('header');
let scrollTicking = false;
window.addEventListener('scroll', function() {
  if (!scrollTicking) {
    requestAnimationFrame(function() {
      header.classList.toggle('scrolled', window.scrollY > 10);
      scrollTicking = false;
    });
    scrollTicking = true;
  }
});

// ===== DESKTOP MEGA MENUS =====
const triggers = document.querySelectorAll('.nav-trigger');
const menus = document.querySelectorAll('.mega-menu');
let activeMenu = null;

function closeAllMenus() {
  menus.forEach(function(m) { m.classList.remove('visible'); });
  triggers.forEach(function(t) { t.classList.remove('active'); });
  activeMenu = null;
}

triggers.forEach(function(trigger) {
  trigger.addEventListener('click', function(e) {
    e.stopPropagation();
    var menuId = trigger.getAttribute('data-menu');
    var menu = document.getElementById(menuId === 'products' ? 'productsMenu' : 'resourcesMenu');

    if (activeMenu === menuId) {
      closeAllMenus();
    } else {
      closeAllMenus();
      menu.classList.add('visible');
      trigger.classList.add('active');
      activeMenu = menuId;
    }
  });

  trigger.addEventListener('mouseenter', function() {
    if (activeMenu) {
      var menuId = trigger.getAttribute('data-menu');
      var menu = document.getElementById(menuId === 'products' ? 'productsMenu' : 'resourcesMenu');
      closeAllMenus();
      menu.classList.add('visible');
      trigger.classList.add('active');
      activeMenu = menuId;
    }
  });
});

// Hover to switch between menus
document.querySelectorAll('.nav-item').forEach(function(item) {
  item.addEventListener('mouseenter', function() {
    if (activeMenu) {
      var trigger = item.querySelector('.nav-trigger');
      if (trigger) {
        var menuId = trigger.getAttribute('data-menu');
        var menu = document.getElementById(menuId === 'products' ? 'productsMenu' : 'resourcesMenu');
        closeAllMenus();
        menu.classList.add('visible');
        trigger.classList.add('active');
        activeMenu = menuId;
      }
    }
  });
});

// Close menus on outside click
document.addEventListener('click', function(e) {
  if (!e.target.closest('.nav-item') && !e.target.closest('.mega-menu')) {
    closeAllMenus();
  }
});

// Close menus on Escape
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') closeAllMenus();
});

// ===== MOBILE NAVIGATION =====
var mobileToggle = document.getElementById('mobileToggle');
var mobileNav = document.getElementById('mobileNav');
var isMobileOpen = false;

mobileToggle.addEventListener('click', function() {
  isMobileOpen = !isMobileOpen;
  mobileToggle.classList.toggle('open', isMobileOpen);
  mobileNav.classList.toggle('open', isMobileOpen);
  document.body.style.overflow = isMobileOpen ? 'hidden' : '';
});

// Mobile submenu toggles
document.querySelectorAll('.mobile-nav-trigger[data-mobile-menu]').forEach(function(trigger) {
  trigger.addEventListener('click', function() {
    var targetId = trigger.getAttribute('data-mobile-menu');
    var submenu = document.getElementById(targetId);
    var isOpen = submenu.classList.contains('open');
    // Close all submenus first
    document.querySelectorAll('.mobile-submenu.open').forEach(function(s) { s.classList.remove('open'); });
    document.querySelectorAll('.mobile-nav-trigger.open').forEach(function(t) { t.classList.remove('open'); });
    if (!isOpen) {
      submenu.classList.add('open');
      trigger.classList.add('open');
    }
  });
});

// ===== CATEGORY FILTERING + SEARCH =====
var pills = document.querySelectorAll('.pill');
var searchInput = document.getElementById('searchInput');
var postCards = document.querySelectorAll('.post-card');
var hiddenPosts = document.getElementById('hiddenPosts');
var showMoreWrap = document.getElementById('showMoreWrap');
var showMoreBtn = document.getElementById('showMoreBtn');
var noResults = document.getElementById('noResults');
var postCount = document.getElementById('postCount');
var activeFilter = 'all';
var searchQuery = '';
var moreShown = false;

function getVisiblePosts() {
  var allCards = document.querySelectorAll('.post-card');
  var visible = [];
  allCards.forEach(function(card) {
    if (card.offsetParent !== null) visible.push(card);
  });
  return visible;
}

function applyFilters() {
  var allCards = document.querySelectorAll('.post-card');
  var anyVisible = false;

  allCards.forEach(function(card) {
    var category = card.getAttribute('data-category');
    var text = card.textContent.toLowerCase();
    var matchesCategory = activeFilter === 'all' || category === activeFilter;
    var matchesSearch = searchQuery === '' || text.indexOf(searchQuery.toLowerCase()) !== -1;

    if (matchesCategory && matchesSearch) {
      card.style.display = '';
      anyVisible = true;
    } else {
      card.style.display = 'none';
    }
  });

  // Handle hidden posts visibility
  if (moreShown) {
    hiddenPosts.style.display = '';
    // Re-check hidden posts children
    hiddenPosts.querySelectorAll('.post-card').forEach(function(card) {
      var category = card.getAttribute('data-category');
      var text = card.textContent.toLowerCase();
      var matchesCategory = activeFilter === 'all' || category === activeFilter;
      var matchesSearch = searchQuery === '' || text.indexOf(searchQuery.toLowerCase()) !== -1;
      card.style.display = (matchesCategory && matchesSearch) ? '' : 'none';
      if (matchesCategory && matchesSearch) anyVisible = true;
    });
  } else {
    hiddenPosts.classList.remove('visible');
    hiddenPosts.style.display = 'none';
  }

  // Toggle no results
  if (!anyVisible) {
    noResults.classList.add('visible');
    showMoreWrap.style.display = 'none';
  } else {
    noResults.classList.remove('visible');
    showMoreWrap.style.display = '';
  }

  // Update count
  var visibleCount = getVisiblePosts().length;
  postCount.textContent = visibleCount + ' article' + (visibleCount !== 1 ? 's' : '');
}

pills.forEach(function(pill) {
  pill.addEventListener('click', function() {
    pills.forEach(function(p) { p.classList.remove('active'); });
    pill.classList.add('active');
    activeFilter = pill.getAttribute('data-filter');
    applyFilters();
  });
});

searchInput.addEventListener('input', function() {
  searchQuery = searchInput.value.trim();
  applyFilters();
});

// ===== SHOW MORE POSTS =====
showMoreBtn.addEventListener('click', function() {
  moreShown = true;
  hiddenPosts.classList.add('visible');
  hiddenPosts.style.display = 'grid';
  showMoreWrap.style.display = 'none';
  // Re-apply filters to the newly visible posts
  applyFilters();
});

// ===== INITIAL COUNT =====
postCount.textContent = '8 articles';

})();
</script>

